const icons = {overview:Layers,firewall:Shield,endpoint:Monitor,backup:Database};
const productChapters=['Resumo executivo','Ambiente do cliente','Pontos de atenção','Simulação de ataque','Como a Concierge atua','Impacto financeiro','Prioridades'];

const read=(key:string,fallback:any)=>{try{return JSON.parse(localStorage.getItem(key)||'null')??fallback;}catch{return fallback;}};
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n);
const download=(data:unknown,name:string)=>{const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const sessionKey=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():`session-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const slug=(s:string)=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/gi,'-').toLowerCase()||'cliente';
const pFields:Record<Module,[keyof Profile,string,string?][]>={
 overview:[['userCount','Usuários','number'],['deviceCount','Computadores e dispositivos','number'],['itTeamSize','Pessoas na equipe de TI','number']],
 firewall:[['userCount','Usuários','number'],['deviceCount','Dispositivos','number'],['itTeamSize','Pessoas na TI','number'],['firewallModel','Modelo atual'],['vlanCount','Quantidade de VLANs','number'],['vlanNames','Redes / VLANs'],['switchCount','Switches','number'],['switchBrand','Fabricante dos switches'],['switchModel','Modelo dos switches'],['apQuantity','Access points','number'],['apBrand','Fabricante dos APs'],['apModel','Modelo dos APs'],['userGrowthEstimate','Crescimento previsto']],
 endpoint:[['deviceCount','Total de dispositivos','number'],['endpointsWindows','Computadores Windows','number'],['windowsVersion','Versões Windows'],['endpointsMac','Computadores Mac','number'],['macVersion','Versões macOS'],['windowsServerCount','Servidores Windows','number'],['windowsServerVersion','Versões Windows Server'],['linuxServerCount','Servidores Linux','number'],['outOfDomainCount','Dispositivos fora do domínio','number']],
 backup:[['backupPhysicalServers','Servidores físicos','number'],['backupVirtualServers','Máquinas virtuais','number'],['backupDesktopsNotebooksCount','Computadores no escopo','number'],['backupSolutionName','Solução atual'],['backupTotalVolumeToProtect','Volume a proteger (com unidade)'],['backupMonthlyGrowth','Crescimento mensal'],['backupDesiredRetention','Retenção desejada'],['backupCurrentFrequency','Frequência atual'],['backupMostCriticalSystem','Serviço prioritário'],['backupMaxAcceptableDowntime','Parada tolerável'],['backupMaxAcceptableDataLoss','Perda de dados tolerável'],['backupM365UsersCount','Usuários Microsoft 365 no escopo','number'],['backupAvailableWindow','Janela para cópia'],['backupMainLinkSpeed','Velocidade para transferência']]
};
const factFields:Record<Module,[string,string,string?][]>={overview:[],firewall:[['sslUsers','Usuários SSL-VPN simultâneos','number'],['ipsecTunnels','Túneis IPsec site-to-site','number'],['ipsecUsers','Usuários IPsec de acesso remoto','number'],['availability','Sistemas e áreas que dependem da rede'],['peakTrafficMbps','Pico conhecido de tráfego agregado em Mbps','number']],endpoint:[['endpointVendor','Fabricante e produto atual'],['endpointLicense','Edição / licença'],['coverage','Cobertura / dispositivos sem agente'],['byod','Dispositivos pessoais e forma de gestão']],backup:[['hosts','Hosts e plataforma de virtualização'],['protectedVMs','VMs efetivamente protegidas'],['nas','NAS: modelo, capacidade e destino'],['backupDest','Destinos das cópias'],['cloudScope','Serviços de nuvem no escopo'],['appScope','Aplicações / bancos / dependências'],['lastTest','Último teste e resultado']]};
const views = ['hub','brief','institutional','qualification','present','report','technical','opening','sessions','complete','onboard-prepare','onboard-present'] as const;
type View=typeof views[number];
type Bundle={version:3;id:string;date:string;profile:Profile;facts:Facts};
export default function V3App(){
 const {profile:p,updateProfile,replaceProfile}=useProfile();
 const [f,setF]=useState<Facts>(()=>read('concierge-v3-facts',{}));
 const [view,setView]=useState<View>('hub');const [mod,setMod]=useState<Module>('overview');const [chapter,setChapter]=useState(0);const [institutionalSlide,setInstitutionalSlide]=useState(0);const [reveal,setReveal]=useState(1);const [sessions,setSessions]=useState<Bundle[]>(()=>read('concierge-v3-sessions',[]));const [toast,setToast]=useState('');const [tech,setTech]=useState(0);const [drawer,setDrawer]=useState(false);const input=useRef<HTMLInputElement>(null);const channel=useRef<BroadcastChannel|null>(null);const [sessionId,setSessionId]=useState<string>(()=>sessionKey());const [showInternalClose,setShowInternalClose]=useState(false);const [sidebarCollapsed,setSidebarCollapsed]=useState<boolean>(()=>read('concierge-v3-sidebar-collapsed',false));
 const route=meetingRoute(f);
 const chapterPath=chapterRoute(f);
 const customerView=['institutional','opening','present','onboard-present'].includes(view);
 const onboardingConfig:OnboardingConfig={service:['firewall','endpoint','backup','mindset'].includes(f.onboardingService||'')?(f.onboardingService as OnboardingConfig['service']):'firewall',sla:['ouro','prata','bronze'].includes(f.onboardingSla||'')?(f.onboardingSla as OnboardingConfig['sla']):'ouro',equipment:f.onboardingEquipment||''};
 const updateOnboarding=(key:keyof OnboardingConfig,value:string)=>set('onboarding'+key.charAt(0).toUpperCase()+key.slice(1),value);
 const openOnboarding=()=>{setView('onboard-prepare');setDrawer(false);};
 useEffect(()=>{try{localStorage.setItem('concierge-v3-sidebar-collapsed',JSON.stringify(sidebarCollapsed));}catch{}},[sidebarCollapsed]);
 const nextTopic=route[route.indexOf(mod)+1];
 const activeChapters=mod==='endpoint'||mod==='backup'?['Resumo executivo','Ambiente do cliente','Pontos de atenção','Simulação interativa','Impacto financeiro','Prioridades']:productChapters;
 // A tela institucional já cobre a atuação da Concierge. No Firewall,
 // preservamos o capítulo no código, mas não o repetimos na reunião.
 const visibleChapters=mod==='firewall'?[0,1,2,3,5,6]:[0,1,2,3,4,5];
 const lastChapter=visibleChapters[visibleChapters.length-1];
 const goChapter=(direction:1|-1)=>{if(direction===1&&chapter===lastChapter){finishTopic();return;}setChapter(c=>{const current=visibleChapters.indexOf(c);const index=current>=0?current:0;return visibleChapters[Math.max(0,Math.min(visibleChapters.length-1,index+direction))];});};
 const startPresentation=()=>{setInstitutionalSlide(0);setView('institutional');setDrawer(false);};
 const startQualification=(m:Module)=>{if(m==='overview')return;setMod(m);set('meetingModules',m);setView('qualification');setDrawer(false);};
 const startProductPresentation=()=>{if(mod==='overview')return;set('meetingModules',mod);setChapter(0);setView('present');setDrawer(false);};
 const presentDirect=(m:Module)=>{if(m==='overview')return;setMod(m);set('meetingModules',m);setChapter(0);setView('present');setDrawer(false);};
 const finishTopic=()=>{if(nextTopic){setMod(nextTopic);setChapter(0);}else {setShowInternalClose(false);setView('complete');}};
 const set=(key:string,value:string)=>setF(prev=>({...prev,[key]:value}));
 const notify=(s:string)=>setToast(s);
 const all=[...analyze(p,f),...firewallOperationalFindings(p,f)];const findings=filterFindings(mod==='overview'?all.filter(x=>route.includes(x.module)):all,mod);const attention=findings.filter(x=>x.state==='attention');const known=findings.filter(x=>x.state==='confirmed');const pending=findings.filter(x=>x.state==='unknown');const stats=contextStats(p,f,mod);const sc=scenario(mod,f);const moduleInfo=modules.find(m=>m.id===mod)!;const Icon=icons[mod];
 useEffect(()=>{try{localStorage.setItem('concierge-v3-facts',JSON.stringify(f));}catch{notify('Não foi possível salvar no navegador. Exporte a sessão para preservar os dados.');}},[f]);
 useEffect(()=>{if(!toast)return;const t=setTimeout(()=>setToast(''),5000);return()=>clearTimeout(t);},[toast]);
 useEffect(()=>{setReveal(1);},[mod,chapter]);
 useEffect(()=>{window.scrollTo({top:0,behavior:'instant' as ScrollBehavior});},[view,mod,chapter]);
 useEffect(()=>{const h=(e:KeyboardEvent)=>{if(view!=='present'||e.altKey||e.ctrlKey||e.metaKey)return;if((e.target as HTMLElement)?.closest('input,textarea,select,[contenteditable=true]'))return;if(e.key==='ArrowRight'){e.preventDefault();goChapter(1);}if(e.key==='ArrowLeft'){e.preventDefault();goChapter(-1);}if(e.key==='Escape')setView('hub');};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h);},[view,mod,chapter,f.meetingModules,f.goal,f.includeSimulation,f.includeService,f.includeImpact]);
 useEffect(()=>{try{channel.current=new BroadcastChannel('concierge-v3-presenter');channel.current.onmessage=e=>{if(view!=='present')return;if(e.data==='next')goChapter(1);if(e.data==='prev')goChapter(-1);};return()=>channel.current?.close();}catch{}},[view,mod,chapter,f.meetingModules,f.goal,f.includeSimulation,f.includeService,f.includeImpact]);
 useEffect(()=>{channel.current?.postMessage({company:p.companyName,module:moduleInfo.label,chapter:chapters[chapter],next:chapters[nextChapter(chapter,chapterPath,1)]||'Encerramento',notes:f.presenterNotes||'Faça uma pausa. Confirme o entendimento do cliente e registre o que falta validar.'});},[p.companyName,mod,chapter,f.presenterNotes,view]);
 useEffect(()=>{let opened:HTMLDetailsElement[]=[];const before=()=>{opened=Array.from(document.querySelectorAll<HTMLDetailsElement>('.v3-report details')).filter(el=>!el.open);opened.forEach(el=>el.open=true);};const after=()=>{opened.forEach(el=>el.open=false);opened=[];};window.addEventListener('beforeprint',before);window.addEventListener('afterprint',after);return()=>{window.removeEventListener('beforeprint',before);window.removeEventListener('afterprint',after);};},[]);
 const select=(m:Module,v:View='present')=>{setMod(m);setChapter(0);setView(v);setDrawer(false);};
 const bundle=():Bundle=>({version:3,id:sessionId,date:new Date().toISOString(),profile:p,facts:f});
 const save=()=>{const b=bundle();const next=[b,...sessions.filter(s=>s.id!==b.id)].slice(0,30);try{localStorage.setItem('concierge-v3-sessions',JSON.stringify(next));setSessions(next);notify('Sessão salva neste navegador.');}catch{notify('Espaço insuficiente. Exporte a sessão em JSON.');}};
 const load=(b:Bundle)=>{replaceProfile({...defaultProfile,...b.profile});setF(b.facts||{});setSessionId(b.id||sessionKey());setView('hub');notify('Sessão carregada.');};
 const startNew=()=>{if(!confirm('Iniciar outra sessão? Salve ou exporte o cliente atual antes de continuar.'))return;replaceProfile({...defaultProfile});setF({});setSessionId(sessionKey());setView('brief');};
 const demo=(presentAfter=false)=>{if(!confirm('Gerar um modelo de exemplo? Salve ou exporte a sessão atual antes.'))return;const sample=pickDemoScenario(p.companyName);const useByDemo:Record<string,string>={'Atlas Distribuição':'medium','Nova Era Contábil':'low','Vida Plena Diagnósticos':'medium','Grupo Horizonte Engenharia':'high'};const use=useByDemo[sample.profile.companyName]||'medium';const sampleFacts={...sample.facts,networkUseProfile:use,hasClientVpn:sample.facts.sslUsers&&Number(sample.facts.sslUsers)>0?'yes':'unknown',hasSiteVpn:sample.facts.ipsecTunnels&&Number(sample.facts.ipsecTunnels)>0?'yes':'unknown',afterHours:sample.facts.networkOps==='reactive'?'no':'unknown',playbook:sample.facts.networkOps==='reactive'?'no':'unknown'};replaceProfile({...defaultProfile,...sample.profile,networkUsage:use});setF(sampleFacts);setSessionId(sessionKey());const target=(sample.facts.meetingModules||'firewall') as Module;setMod(target);setChapter(0);setView(presentAfter?'present':'hub');notify(`Modelo de exemplo gerado para ${sample.profile.companyName}.`);};
 const importFile=async(file?:File)=>{if(!file)return;try{if(file.size>5000000)throw Error();const b=JSON.parse(await file.text());if(b.version!==3||!b.profile||typeof b.profile.companyName!=='string'||!b.facts||Array.isArray(b.facts)||Object.values(b.facts).some(v=>typeof v!=='string'))throw Error();for(const [k,v]of Object.entries(defaultProfile)){if(k in b.profile && typeof b.profile[k]!==typeof v && !(k==='companyLogo'&&(b.profile[k]===null||typeof b.profile[k]==='string')))throw Error();}if(!Array.isArray(b.profile.internetLinks)||b.profile.internetLinks.some((l:any)=>!l||typeof l.provider!=='string'||typeof l.speed!=='string'))throw Error();if(b.profile.companyLogo&&!/^data:image\/(png|jpeg|webp);base64,/.test(b.profile.companyLogo))throw Error();if(!confirm('Substituir a sessão atual pelos dados importados?'))return;load(b);}catch{notify('Arquivo inválido. Use uma sessão JSON exportada pela V3 (até 5 MB).');}finally{if(input.current)input.current.value='';}};
 const presentWindow=()=>{const w=window.open('','concierge-v3-notes','width=520,height=640');if(!w){notify('Permita a abertura da janela do apresentador.');return;}w.document.title='Condução · Concierge';w.document.body.replaceChildren();w.document.body.style.cssText='background:#07101f;color:#e2e8f0;font:18px system-ui;padding:28px;line-height:1.6';const h=w.document.createElement('h1');h.textContent='Painel do apresentador';w.document.body.append(h);const box=w.document.createElement('div');w.document.body.append(box);const render=(s:any)=>{box.replaceChildren();for(const text of [s.company,s.module,s.chapter,'A seguir: '+s.next,s.notes]){const el=w.document.createElement('p');el.textContent=text;box.append(el);}};const c=new BroadcastChannel('concierge-v3-presenter');c.onmessage=e=>{if(typeof e.data==='object')render(e.data);};render({company:p.companyName,module:moduleInfo.label,chapter:chapters[chapter],next:chapters[nextChapter(chapter,chapterPath,1)]||'Encerramento',notes:f.presenterNotes||'Confirme o entendimento antes de avançar.'});for(const [text,cmd]of [['Voltar','prev'],['Avançar','next']]){const b=w.document.createElement('button');b.textContent=text;b.style.cssText='padding:12px 22px;margin:8px;background:#22d3ee;border:0;border-radius:10px;cursor:pointer';b.onclick=()=>c.postMessage(cmd);w.document.body.append(b);}w.onbeforeunload=()=>c.close();};
 const field=(key:string,title:string,value:string,onChange:(v:string)=>void,type='text')=><label className="v3-field" key={key}><span>{title}</span><input type={type} min={type==='number'?0:undefined} value={value} onChange={e=>onChange(e.target.value)} placeholder="A confirmar" /></label>;
 const renderQuestions=(keys:string[])=><div className="v3-questions">{keys.map(key=>questions.find(q=>q.key===key)!).filter(q=>q&&applicable(q,f)).map(q=><fieldset key={q.key}><legend>{q.label}</legend>{q.help&&<p>{q.help}</p>}<div className="v3-choices">{q.options.map(([val,text])=><button key={val} aria-pressed={(f[q.key]||'unknown')===val} onClick={()=>set(q.key,val)} className={(f[q.key]||'unknown')===val?'selected':''}><span className="v3-radio">{(f[q.key]||'unknown')===val&&<span/>}</span>{text}</button>)}</div></fieldset>)}</div>;
 const renderProfile=(keys:string[])=>pFields[mod].filter(([key])=>keys.includes(String(key))).map(([key,title,type])=>field(String(key),title,String(p[key]||''),v=>updateProfile({[key]:type==='number'?Math.max(0,Number(v)||0):v}),type));
 const renderFacts=(keys:string[])=>factFields[mod].filter(([key])=>keys.includes(key)).map(([key,title,type])=>field(key,title,f[key]??'',v=>set(key,v),type));
 const moduleFields=(m:Module)=>m==='endpoint'?<div className="v3-prep-groups">
 <section><span className="v3-kicker">01 · PARQUE E COBERTURA</span><h3>Quais equipamentos precisam ser protegidos?</h3><div className="v3-form-grid">{renderProfile(['deviceCount','endpointsWindows','windowsVersion','endpointsMac','macVersion','windowsServerCount','windowsServerVersion','linuxServerCount','outOfDomainCount'])}</div></section>
 <section><span className="v3-kicker">02 · SOLUÇÃO ATUAL</span><h3>O que existe hoje e qual é a cobertura real?</h3><div className="v3-form-grid">{renderFacts(['endpointVendor','endpointLicense','coverage','byod'])}</div>{renderQuestions(['protection','console'])}</section>
 <section><span className="v3-kicker">03 · ALERTAS E RESPOSTA</span><h3>Quem recebe um alerta e o que acontece depois?</h3>{renderQuestions(['endpointOps','response'])}</section>
 <section><span className="v3-kicker">04 · ROTINA DO AMBIENTE</span><h3>Como o parque é mantido no dia a dia?</h3>{renderQuestions(['patch','admin'])}</section></div>
 :m==='backup'?<div className="v3-prep-groups">
 <section><span className="v3-kicker">01 · ESCOPO</span><h3>O que precisa estar disponível quando a empresa precisar recuperar?</h3><div className="v3-form-grid">{renderProfile(['backupPhysicalServers','backupVirtualServers','backupDesktopsNotebooksCount','backupM365UsersCount'])}{renderFacts(['hosts','protectedVMs','nas','cloudScope','appScope'])}</div>{renderQuestions(['backup'])}</section>
 <section><span className="v3-kicker">02 · VOLUMETRIA E ROTINA</span><h3>Quanto dado existe e como as cópias acontecem?</h3><div className="v3-form-grid">{renderProfile(['backupSolutionName','backupTotalVolumeToProtect','backupMonthlyGrowth','backupDesiredRetention','backupCurrentFrequency','backupAvailableWindow','backupMainLinkSpeed'])}{renderFacts(['backupDest'])}</div>{renderQuestions(['backupOps'])}</section>
 <section><span className="v3-kicker">03 · RECUPERAÇÃO</span><h3>O que precisa voltar primeiro e em quanto tempo?</h3><div className="v3-form-grid">{renderProfile(['backupMostCriticalSystem','backupMaxAcceptableDowntime','backupMaxAcceptableDataLoss'])}{renderFacts(['lastTest'])}</div>{renderQuestions(['tested','recoveryPlan'])}</section>
 <section><span className="v3-kicker">04 · PROTEÇÃO DAS CÓPIAS</span><h3>As cópias resistem ao mesmo incidente que afeta a produção?</h3>{renderQuestions(['isolated'])}</section></div>
 :<div className="v3-form-grid">{renderProfile(pFields[m].map(([k])=>String(k)))}{renderFacts(factFields[m].map(([k])=>k))}</div>;
 return <div className={`v3-app ${sidebarCollapsed?'sidebar-collapsed':''} ${customerView?'customer-mode':''} ${view==='institutional'?'institutional-mode':''} ${view==='onboard-present'?'onboarding-mode':''} ${view==='present'&&chapter===2?'simulation-active':''}`}><CyberBackdrop/><input type="file" accept="application/json,.json" ref={input} hidden onChange={e=>importFile(e.target.files?.[0])}/><header className="v3-header no-print"><button className="brand-button" onClick={()=>setView('hub')} aria-label="Início"><ConciergeBrandLockup compact/></button><span className="v3-version">V3.7 · experiência de reunião</span>{(view==='onboard-prepare'||view==='onboard-present')&&<div className="v3-onboarding-client-head">{p.companyLogo&&<img src={p.companyLogo} alt={`Logo de ${p.companyName||'cliente'}`}/>}<span><b>{p.companyName||'Onboarding'}</b><small>{onboardingConfig.equipment||`${onboardingConfig.service} · SLA ${onboardingConfig.sla.toUpperCase()}`}</small></span></div>}{!customerView&&<div className="v3-header-actions"><button className="v3-icon" onClick={save} title="Salvar sessão" aria-label="Salvar sessão"><Save size={19}/></button><button className="v3-icon" onClick={()=>download(bundle(),`concierge-${slug(p.companyName)}.json`)} title="Exportar sessão" aria-label="Exportar sessão"><Download size={19}/></button><button className="v3-icon" onClick={()=>input.current?.click()} title="Importar sessão" aria-label="Importar sessão"><Upload size={19}/></button><button className="v3-icon" onClick={()=>setView('report')} title="Relatório" aria-label="Relatório"><FileText size={19}/></button><button className="v3-icon" onClick={()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>notify('Tela cheia indisponível.'));}} title="Tela cheia" aria-label="Tela cheia"><Maximize2 size={19}/></button><button className="v3-icon mobile-menu" onClick={()=>setDrawer(!drawer)} aria-label="Abrir menu"><Menu size={20}/></button></div>}{customerView&&<div className="v3-header-actions customer-actions"><button className="v3-icon" onClick={()=>{if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>notify('Tela cheia indisponível.'));}} title="Tela cheia" aria-label="Tela cheia"><Maximize2 size={19}/></button>{view==='onboard-present'&&<button className="v3-text-btn" onClick={()=>window.print()}>Salvar PDF</button>}<button className="v3-text-btn workspace-return" onClick={()=>setView(view==='onboard-present'?'onboard-prepare':'hub')}>{view==='onboard-present'?'Configurar onboarding':'Sair da apresentação'}</button></div>}</header>
 {!customerView&&<aside className={`v3-sidebar no-print ${drawer?'open':''}`} aria-label="Navegação principal">
 <div className="v3-sidebar-top"><div className="v3-client-name" title={p.companyName||'Sua próxima reunião'}><span>{p.companyName||'Sua próxima reunião'}</span><small>Espaço de preparação</small></div><button type="button" className="v3-sidebar-toggle" aria-label={sidebarCollapsed?'Expandir menu':'Recolher menu'} title={sidebarCollapsed?'Expandir menu':'Recolher menu'} aria-expanded={!sidebarCollapsed} onClick={()=>setSidebarCollapsed(v=>!v)}>{sidebarCollapsed?<PanelLeftOpen size={20}/>:<PanelLeftClose size={20}/>}</button></div>
 <div className="v3-sidebar-section-label">REUNIÃO</div>
 <button title="Preparar o cliente" aria-label="Preparar o cliente" className={view==='brief'?'nav-active':''} onClick={()=>{setView('brief');setDrawer(false);}}><FileText size={19}/><span className="v3-nav-text">Preparar o cliente</span></button>
 <button title="Apresentação institucional" aria-label="Apresentação institucional" className={view==='institutional'?'nav-active':''} onClick={startPresentation}><Play size={19}/><span className="v3-nav-text">Apresentação institucional</span></button>
 <div className="v3-sidebar-section-label">QUALIFICAÇÃO</div>
 <button title="Concierge Firewall" aria-label="Qualificar Concierge Firewall" className={view==='qualification'&&mod==='firewall'?'nav-active':''} onClick={()=>startQualification('firewall')}><Shield size={19}/><span className="v3-nav-text">Concierge Firewall</span></button>
 <button title="Concierge Endpoint" aria-label="Qualificar Concierge Endpoint" className={view==='qualification'&&mod==='endpoint'?'nav-active':''} onClick={()=>startQualification('endpoint')}><Monitor size={19}/><span className="v3-nav-text">Concierge Endpoint</span></button>
 <button title="Concierge Backup" aria-label="Qualificar Concierge Backup" className={view==='qualification'&&mod==='backup'?'nav-active':''} onClick={()=>startQualification('backup')}><Database size={19}/><span className="v3-nav-text">Concierge Backup</span></button>
 <div className="v3-sidebar-section-label">APRESENTAÇÕES</div>
 <button title="Apresentar Firewall" aria-label="Apresentar Firewall" className={view==='present'&&mod==='firewall'?'nav-active':''} onClick={()=>presentDirect('firewall')}><Play size={19}/><span className="v3-nav-text">Apresentar Firewall</span></button>
 <button title="Apresentar Endpoint" aria-label="Apresentar Endpoint" className={view==='present'&&mod==='endpoint'?'nav-active':''} onClick={()=>presentDirect('endpoint')}><Play size={19}/><span className="v3-nav-text">Apresentar Endpoint</span></button>
 <button title="Apresentar Backup" aria-label="Apresentar Backup" className={view==='present'&&mod==='backup'?'nav-active':''} onClick={()=>presentDirect('backup')}><Play size={19}/><span className="v3-nav-text">Apresentar Backup</span></button>
 <div className="v3-sidebar-bottom">
 <button title="Sessões salvas" aria-label="Sessões salvas" className={view==='sessions'?'nav-active':''} onClick={()=>{setView('sessions');setDrawer(false);}}><Save size={18}/><span className="v3-nav-text">Sessões salvas</span></button>
 <button title="Painel do apresentador" aria-label="Painel do apresentador" onClick={presentWindow}><Monitor size={18}/><span className="v3-nav-text">Painel do apresentador</span></button>
 <button title="Nova sessão" aria-label="Nova sessão" onClick={startNew}><Plus size={18}/><span className="v3-nav-text">Nova sessão</span></button>
 <div className="v3-sidebar-section-label">DEPOIS DA VENDA</div>
 <button title="Onboarding pós-venda" aria-label="Onboarding pós-venda" className={view==='onboard-prepare'||view==='onboard-present'?'nav-active':''} onClick={openOnboarding}><CheckCircle2 size={18}/><span className="v3-nav-text">Onboarding pós-venda</span></button>
 </div></aside>}
 <main className="v3-main">
 {view==='sessions'&&<><div className="v3-page-heading"><span className="v3-kicker">RETOMAR CONTEXTO</span><h1>Sessões salvas</h1></div><section className="v3-panel v3-session-panel"><h3>Sessões salvas</h3>{sessions.length===0?<p>Nenhuma sessão salva. Use o ícone de salvar para registrar esta conversa.</p>:sessions.map(s=><div className="v3-session-row" key={s.id}><button className="v3-text-btn" onClick={()=>{if(confirm('Carregar esta sessão e substituir o rascunho atual?'))load(s);}}>{s.profile.companyName||'Cliente sem nome'}<small>{new Date(s.date).toLocaleString('pt-BR')}</small></button><button className="v3-icon" aria-label="Excluir sessão" onClick={()=>{if(!confirm('Excluir esta sessão salva?'))return;const next=sessions.filter(x=>x.id!==s.id);try{localStorage.setItem('concierge-v3-sessions',JSON.stringify(next));setSessions(next);}catch{notify('Não foi possível excluir.');}}}><X size={16}/></button></div>)}</section></>}
 {view==='hub'&&<><section className="v3-hero executive-surface v3-flow-hero"><div><span className="v3-kicker">CONCIERGE INTERACTIVE EXPERIENCE</span><h1>Uma conversa.<br/><em>O ambiente em foco.</em></h1><p className="v3-lead">{p.companyName?`A conversa com ${p.companyName} começa pelo contexto da empresa. Depois, avançamos para o ambiente, os pontos que merecem atenção e os próximos passos.`:'Prepare a reunião, apresente como trabalhamos e aprofunde as necessidades de segurança que fizerem sentido para o cliente.'}</p><div className="v3-actions"><button className="v3-btn" onClick={()=>setView('brief')}>Preparar cliente <ArrowRight size={18}/></button><button className="v3-btn secondary" onClick={startPresentation}>Abrir apresentação institucional</button></div><div className="v3-trust"><span>SOC 24/7</span><span>Grupo QOS Tecnologia</span><span>ISO 27001</span><span>ISO 37001</span></div></div><div className="v3-hero-brand"><ConciergeBrandLockup/>{p.companyLogo&&<div className="v3-client-logo"><img src={p.companyLogo} alt={p.companyName}/></div>}<p>{p.companyName?'Apresentação personalizada pronta para a reunião':'Adicione nome e logo para personalizar a apresentação'}</p></div></section>
 <section className="v3-flow-map"><div className="v3-section-heading"><div><span className="v3-kicker">FLUXO DA CONVERSA</span><h2>Do primeiro contato ao próximo passo.</h2></div><div className="v3-inline-actions"><button className="v3-btn secondary" onClick={()=>demo(false)}>Gerar modelo de exemplo</button><button className="v3-btn hub-demo-cta" onClick={()=>demo(true)}>Gerar exemplo e apresentar <ArrowRight size={16}/></button></div></div><div className="v3-flow-steps"><article><span>01</span><h3>Preparar</h3><p>Nome, logo, contato e contexto que você já conhece.</p><button className="v3-text-btn" onClick={()=>setView('brief')}>Abrir preparação</button></article><article><span>02</span><h3>Apresentar</h3><p>Institucional, forma de atuação, portfólio e operação da Concierge.</p><button className="v3-text-btn" onClick={startPresentation}>Abrir institucional</button></article><article><span>03</span><h3>Qualificar</h3><p>Escolha Firewall, Endpoint ou Backup conforme a conversa evoluir.</p><div className="v3-inline-actions"><button onClick={()=>startQualification('firewall')}>Firewall</button><button onClick={()=>startQualification('endpoint')}>Endpoint</button><button onClick={()=>startQualification('backup')}>Backup</button></div></article><article><span>04</span><h3>Apresentar cenário</h3><p>Use as respostas confirmadas para conduzir uma apresentação específica da frente escolhida.</p><div className="v3-inline-actions"><button onClick={()=>presentDirect('firewall')}>Firewall</button><button onClick={()=>presentDirect('endpoint')}>Endpoint</button><button onClick={()=>presentDirect('backup')}>Backup</button></div></article></div></section>
 <section className="v3-ecosystem-strip"><div><span className="v3-kicker">DEPOIS DO DE ACORDO</span><h2>O mesmo ecossistema continua no onboarding.</h2><p>Cadastro, ambiente, responsáveis e informações de implantação ficam em uma área interna. Essa tela não faz parte do compartilhamento com o cliente.</p></div><button className="v3-btn secondary" onClick={openOnboarding}>Preparar onboarding pós-venda</button></section></>}
 {view==='brief'&&<><div className="v3-page-heading"><span className="v3-kicker">01 · PREPARAR CLIENTE</span><h1>O mínimo necessário antes de compartilhar a tela.</h1><p>Esta etapa é interna. Personalize a apresentação e registre apenas o contexto que você já conhece. A qualificação acontece depois do institucional.</p></div><section className="v3-panel v3-preparation-panel"><div className="v3-form-grid">{field('company','Empresa',p.companyName,v=>updateProfile({companyName:v}))}{field('contact','Contato',p.contactName,v=>updateProfile({contactName:v}))}{field('role','Cargo',p.contactRole,v=>updateProfile({contactRole:v}))}{field('sector','Setor',p.sector,v=>updateProfile({sector:v}))}<label className="v3-field"><span>Logo do cliente (PNG, JPEG ou WebP, até 1 MB)</span><input type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>{const file=e.target.files?.[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1024*1024){notify('Use PNG, JPEG ou WebP com até 1 MB.');return;}const r=new FileReader();r.onload=()=>updateProfile({companyLogo:String(r.result)});r.readAsDataURL(file);}}/></label></div><label className="v3-field"><span>Contexto que já conhecemos</span><textarea value={f.context||''} onChange={e=>set('context',e.target.value)} placeholder="Ex.: veio pelo LinkedIn, primeira conversa, ainda sem dor técnica confirmada."/></label><details className="v3-subsection"><summary>Notas privadas para condução</summary><textarea aria-label="Notas de condução" value={f.presenterNotes||''} onChange={e=>set('presenterNotes',e.target.value)} placeholder="Perguntas que você quer lembrar, participantes, restrições ou contexto comercial."/><p>Essas notas não aparecem na apresentação compartilhada.</p></details><div className="v3-prep-preview"><div><span className="v3-kicker">PRONTO PARA COMPARTILHAR</span><h3>{p.companyName||'Cliente ainda sem nome'}</h3><p>A apresentação institucional usa automaticamente o nome e a logo definidos acima.</p></div>{p.companyLogo&&<div className="v3-client-logo"><img src={p.companyLogo} alt={p.companyName}/></div>}</div><div className="v3-actions"><button className="v3-btn" onClick={startPresentation}>Abrir apresentação institucional <ArrowRight size={18}/></button><button className="v3-btn secondary" onClick={save}>Salvar sessão</button></div></section></>}
 {view==='institutional'&&<InstitutionalPresentation profile={p} slide={institutionalSlide} onSlide={setInstitutionalSlide} onFinish={()=>{set('institutionalPresented','yes');setView('hub');notify('Institucional concluído. Pare o compartilhamento antes de iniciar a qualificação.');}}/>}
 {view==='qualification'&&<><div className="v3-internal-banner"><LockKeyhole size={19}/><div><b>Área interna do apresentador</b><span>Pare o compartilhamento antes de preencher esta etapa.</span></div></div><div className="v3-page-heading"><span className="v3-kicker">03 · QUALIFICAÇÃO E DIMENSIONAMENTO</span><h1>Agora, uma frente por vez.</h1><p>Escolha o assunto que ganhou prioridade na conversa. As perguntas abaixo servem para entender o ambiente e preparar a próxima apresentação.</p></div><div className="v3-product-selector">{modules.filter(m=>m.id!=='overview').map(m=>{const I=icons[m.id];return <button key={m.id} className={mod===m.id?'active':''} onClick={()=>{setMod(m.id);set('meetingModules',m.id);}}><I size={25}/><span>{m.label}</span><small>{m.sub}</small></button>;})}</div><section className="v3-panel v3-qualification-panel"><div className="v3-qualification-heading"><div><span className="v3-kicker">AMBIENTE DO CLIENTE</span><h2>Dimensionamento de {moduleLabel(mod)}</h2><p>O que ainda não souber pode ficar em aberto. O objetivo é sair com dados suficientes para dimensionar com segurança.</p></div><div className="v3-qualification-summary">{contextStats(p,f,mod).map(([k,v])=><div key={k}><span>{k}</span><b>{v}</b></div>)}</div></div>{mod==='firewall'?<FirewallQualification profile={p} facts={f} updateProfile={updateProfile} setFact={set} onPresent={()=>presentDirect('firewall')}/>:mod==='endpoint'||mod==='backup'?<ServiceQualification key={mod} service={mod} profile={p} facts={f} updateProfile={updateProfile} setFact={set} onPresent={()=>presentDirect(mod)}/>:moduleFields(mod)}<label className="v3-field"><span>Observações desta frente</span><textarea value={f['notes_'+mod]||''} onChange={e=>set('notes_'+mod,e.target.value)} placeholder="Registre detalhes que não cabem nos campos acima."/></label><div className={`v3-qualification-actions ${mod==='firewall'?'firewall-qualification-actions':''}`}><div><b>Sem tempo para continuar hoje?</b><p>Salve a sessão e retome deste ponto na próxima reunião.</p></div><div className="v3-actions"><button className="v3-btn secondary" onClick={save}>Salvar e continuar depois</button><button className="v3-btn product-presentation-cta" onClick={startProductPresentation}><Play size={18}/> Abrir apresentação executiva de {moduleLabel(mod)} <ArrowRight size={18}/></button></div></div></section></>}
 {view==='opening'&&<section className="v3-hero executive-surface meeting-opening"><div><span className="v3-kicker">CONCIERGE · CONVERSA COM {p.companyName||'SUA EMPRESA'}</span><h1>{f.goal||'Vamos entender suas prioridades.'}</h1><p className="v3-lead">{f.context||'Confirmar o cenário, discutir o que merece atenção e combinar os próximos passos.'}</p><div className="meeting-agenda"><span>01 · Seu contexto</span><span>02 · Pontos para discutir</span><span>03 · Próximos passos</span></div><p>Temas combinados: {route.map(moduleLabel).join(' · ')}</p><button className="v3-btn" onClick={()=>select(route[0])}>Começar por {moduleLabel(route[0])}<ArrowRight size={17}/></button></div><div className="v3-hero-brand"><ConciergeBrandLockup/>{p.companyLogo&&<div className="v3-client-logo"><img src={p.companyLogo} alt={p.companyName}/></div>}</div></section>}
 {view==='complete'&&<section className="v3-stage fw-internal-finish"><span className="v3-kicker">APRESENTAÇÃO FINALIZADA</span><h1>Conversa concluída.</h1>{!showInternalClose?<><p className="v3-lead">O conteúdo apresentado ao cliente terminou. Interrompa o compartilhamento antes de registrar informações internas e próximos passos comerciais.</p><div className="v3-actions"><button className="v3-btn" onClick={()=>setShowInternalClose(true)}>Abrir registro interno da reunião <ArrowRight size={18}/></button><button className="v3-btn secondary" onClick={()=>setView('hub')}>Voltar ao início</button></div></>:<><div className="v3-internal-banner"><LockKeyhole size={19}/><div><b>Registro interno</b><span>Responsáveis, ações e datas ficam na sessão do apresentador.</span></div></div><div className="fw-internal-action-grid">{route.map(m=><article key={m}><h3>{moduleLabel(m)}</h3><label className="v3-field"><span>Próxima ação combinada</span><textarea value={f['decision_'+m]||''} onChange={e=>set('decision_'+m,e.target.value)} placeholder="Ex.: revisar sizing com pré-vendas"/></label><label className="v3-field"><span>Quem puxa o próximo contato</span><input value={f['owner_'+m]||''} onChange={e=>set('owner_'+m,e.target.value)} placeholder="Concierge / cliente"/></label><label className="v3-field"><span>Data combinada</span><input type="date" value={f['date_'+m]||''} onChange={e=>set('date_'+m,e.target.value)}/></label></article>)}</div><div className="v3-actions"><button className="v3-btn" onClick={save}>Salvar reunião <Save size={16}/></button><button className="v3-btn secondary" onClick={()=>setView('report')}>Abrir síntese</button></div></>}</section>}
 {view==='present'&&<>{chapter!==0&&mod==='firewall'&&![2,5].includes(chapter)&&<div className="v3-presentation-heading product-presentation-heading"><div><span className="v3-kicker">{moduleInfo.label.toUpperCase()} · {p.companyName||'AMBIENTE EM LEVANTAMENTO'}</span><h1>{activeChapters[chapter]||'Apresentação executiva'}</h1></div></div>}<details className="v3-presentation-tools"><summary>Conduzir apresentação · {moduleInfo.label}</summary><div className="v3-actions">{route.map(m=><button className="v3-btn secondary" key={m} onClick={()=>select(m)}>{moduleLabel(m)}</button>)}</div><nav className="v3-chapter-nav" aria-label="Navegar pela apresentação">{visibleChapters.map(i=><button aria-current={chapter===i?'step':undefined} key={activeChapters[i]} className={chapter===i?'active':''} onClick={()=>setChapter(i)}>{activeChapters[i]}</button>)}</nav><button className="v3-text-btn" onClick={()=>setView('qualification')}>Voltar à qualificação</button></details>
 <ProductStoryPresentation module={mod} chapter={chapter} profile={p} facts={f} findings={findings} updateFact={set} money={money}/>
 <footer className="v3-presentation-footer"><button className="v3-btn secondary" onClick={()=>goChapter(-1)} disabled={chapter===0}><ArrowLeft size={17}/>Voltar</button><span>{moduleInfo.label} · {activeChapters[chapter]}</span><button className="v3-btn" onClick={()=>chapter===lastChapter?finishTopic():goChapter(1)}>{chapter===lastChapter?(nextTopic?'Próximo tema: '+moduleLabel(nextTopic):'Concluir reunião'):'Continuar'}<ArrowRight size={17}/></button></footer></>}


 {view==='onboard-prepare'&&<><div className="v3-internal-banner"><LockKeyhole size={19}/><div><b>Preparação interna pós-venda</b><span>Nome e logo já vêm do cadastro do cliente. Confirme SLA e equipamento antes de compartilhar.</span></div></div><ConciergeOnboarding profile={p} config={onboardingConfig} setConfig={updateOnboarding} presenting={false} onStart={()=>setView('onboard-present')} onExit={()=>setView('hub')}/><div className="v3-actions v3-onboarding-tech-access"><button className="v3-btn secondary" onClick={()=>setView('technical')}>Abrir cadastro técnico interno <ArrowRight size={16}/></button><button className="v3-btn secondary" onClick={()=>setView('brief')}>Alterar nome ou logo do cliente</button></div></>}
 {view==='onboard-present'&&<ConciergeOnboarding profile={p} config={onboardingConfig} setConfig={updateOnboarding} presenting={true} onStart={()=>{}} onExit={()=>setView('onboard-prepare')}/>}
 {view==='technical'&&<><div className="v3-internal-banner"><LockKeyhole size={19}/><div><b>Área interna pós-venda</b><span>Use depois do de acordo para consolidar os dados necessários à implantação.</span></div></div><div className="v3-page-heading"><span className="v3-kicker">ONBOARDING PÓS-VENDA</span><h1>Do fechamento para a implantação.</h1><p>Cadastro, rede, endpoints, backup, governança e revisão ficam reunidos aqui para organizar a passagem comercial e técnica.</p></div><div className="v3-tabs">{['Identificação','Rede','Endpoint','Backup','Governança','Estratégia','Revisão'].map((s,i)=><button key={s} className={tech===i?'active':''} onClick={()=>setTech(i)}>{s}</button>)}</div><div className="v3-panel">{[<Step1/>,<Step2/>,<Step3/>,<Step4/>,<Step5/>,<Step6/>,<Step7/>][tech]}</div></>}
 {view==='report'&&<><div className="v3-actions no-print"><button className="v3-btn" onClick={()=>window.print()}><Download size={17}/>Imprimir / salvar PDF</button><button className="v3-btn secondary" onClick={()=>download(bundle(),`concierge-${slug(p.companyName)}.json`)}>Exportar sessão completa</button></div><article className="v3-report"><ConciergeBrandLockup compact/><span className="v3-kicker">SÍNTESE DA CONVERSA</span><h1>{p.companyName||'Empresa em levantamento'}</h1><p>{new Date().toLocaleDateString('pt-BR')} · {p.contactName||'Contato a confirmar'}</p><p><b>Objetivo: </b>{f.goal||'A definir'}</p>{f.context&&<p>{f.context}</p>}<EnvironmentGrade findings={all.filter(x=>route.includes(x.module))}/>{modules.filter(m=>route.includes(m.id)).map(m=><section key={m.id}><h2>{m.label}</h2><EnvironmentGrade findings={filterFindings(all,m.id)}/><div className="v3-stat-grid">{contextStats(p,f,m.id).map(([k,v])=><div key={k}><b>{k}</b><p>{v}</p></div>)}</div>{filterFindings(all,m.id).map(x=><div className="v3-report-finding" key={x.id}><h3>{x.title} · {x.state==='attention'?'Atenção':x.state==='confirmed'?'Informado':'A confirmar'}</h3><p>{x.evidence}</p><p>{x.action}</p><PrivacyContext finding={x}/></div>)}{f['decision_'+m.id]&&<p><b>Combinado: </b>{f['decision_'+m.id]}</p>}{f['owner_'+m.id]&&<p>Responsável: {f['owner_'+m.id]} · {f['date_'+m.id]||'Data a definir'}</p>}</section>)}{f.decision_overview&&<p><b>Encaminhamento geral: </b>{f.decision_overview}</p>}<References technical/><footer>Diagnóstico inicial baseado nas informações fornecidas. Sem varredura, auditoria ou validação técnica automática. Simulações financeiras e notas internas não integram esta devolutiva.</footer></article></>}
 </main>{toast&&<div className="v3-toast" role="status">{toast}<button onClick={()=>setToast('')} aria-label="Fechar aviso"><X size={16}/></button></div>}</div>;
}

function toCount(value:any){const n=Number(value);return Number.isFinite(n)&&n>0?n:0;}
function plural(n:number,one:string,many:string){return `${n} ${n===1?one:many}`;}
function storyHighlights(findings:any[]){return (findings.length?findings:[{id:'pending-general',state:'unknown',title:'Mais informações precisam ser confirmadas',meaning:'Ainda faltam respostas para consolidar uma leitura mais precisa do ambiente.',evidence:'Sem verificação técnica automática.'}]).slice(0,4);}
function environmentHeadline(mod:Module, companyName?:string){const company=companyName||'sua empresa';if(mod==='firewall')return `Assim enxergamos a rede e os acessos de ${company}.`;if(mod==='endpoint')return `Assim enxergamos o parque de dispositivos de ${company}.`;return `Assim enxergamos os dados e a continuidade de ${company}.`;}
function environmentLead(mod:Module, companyName?:string){const company=companyName||'a empresa';if(mod==='firewall')return `O objetivo aqui é materializar a borda, os acessos e a estrutura de rede informada por ${company}, para que a conversa parta do ambiente real e não de uma apresentação genérica.`;if(mod==='endpoint')return `Antes de discutir produto, precisamos visualizar o parque, a cobertura e os pontos cegos informados por ${company}.`;return `Antes de falar em backup, precisamos visualizar o que sustenta a operação, o que precisa voltar primeiro e quanto tempo ${company} tolera ficar parada.`;}
function analysisHeadline(mod:Module){if(mod==='firewall')return 'O que esse desenho sugere sobre disponibilidade, acesso e controle.';if(mod==='endpoint')return 'O que esse parque sugere sobre cobertura, visibilidade e resposta.';return 'O que esse cenário sugere sobre recuperação, continuidade e confiança no retorno.';}
function analysisLead(attention:number, known:number, pending:number){if(attention>0)return 'Os pontos abaixo ajudam a explicar onde a conversa merece mais atenção primeiro.';if(known>0)return 'Já existem controles informados. Agora o foco é entender se eles estão cobrindo o que a operação realmente precisa.';if(pending>0)return 'Ainda faltam confirmações. Mesmo assim, já é possível sinalizar o que precisa ser validado para não avançar no escuro.';return 'Use este quadro para organizar o que já sabemos e o que ainda precisa de confirmação.';}
function problemHeadline(mod:Module){if(mod==='firewall')return 'Quais situações costumam transformar rede e acesso em problema operacional?';if(mod==='endpoint')return 'Quais situações costumam transformar um dispositivo em porta de entrada ou perda de tempo?';return 'Quais situações costumam transformar backup em urgência real?';}
function problemLead(mod:Module){if(mod==='firewall')return 'O cenário abaixo ilustra como indisponibilidade, acesso remoto e políticas mal alinhadas podem virar impacto direto na operação.';if(mod==='endpoint')return 'O cenário abaixo ajuda a traduzir sinais do parque em algo que o cliente reconhece no dia a dia.';return 'O cenário abaixo ajuda a traduzir cópia, retenção e recuperação em efeito prático quando a empresa precisa voltar a operar.';}
function serviceHeadline(mod:Module){if(mod==='firewall')return 'Como a Concierge entra na borda, nos acessos e na operação da rede.';if(mod==='endpoint')return 'Como a Concierge entra na proteção, investigação e resposta do parque.';return 'Como a Concierge entra na rotina de cópias, falhas e recuperação.';}
function moduleImpactNarratives(mod:Module){if(mod==='firewall')return [{title:'Operação',body:'Falhas na borda ou na segmentação tendem a aparecer como indisponibilidade, dificuldade de acesso e pressão sobre a equipe.'},{title:'Tempo',body:'Sem visibilidade suficiente, a investigação de lentidão, bloqueios ou acessos remotos pode consumir tempo demais.'},{title:'Financeiro',body:'Paradas, improdutividade e esforço de recuperação podem virar custo mesmo quando o incidente não chega a ser grave.'}];if(mod==='endpoint')return [{title:'Operação',body:'Baixa cobertura ou pouca visibilidade nos dispositivos aumenta o tempo para entender o que aconteceu e onde aconteceu.'},{title:'Tempo',body:'Quanto mais manual for a investigação, mais a equipe se afasta da rotina operacional.'},{title:'Financeiro',body:'Incidentes em endpoints podem gerar perda de produtividade, resposta emergencial e pressão sobre áreas críticas.'}];return [{title:'Operação',body:'Sem clareza sobre o que está protegido e como recuperar, a continuidade fica dependente de improviso.'},{title:'Tempo',body:'RPO e RTO mal definidos costumam aparecer quando a empresa precisa voltar e ninguém sabe exatamente o que esperar.'},{title:'Financeiro',body:'Parada prolongada, retrabalho e recuperação fora do planejado viram custo rapidamente.'}];}
function conciergeActions(mod:Module){if(mod==='firewall')return ['Acompanhar borda, políticas e sinais relevantes do ambiente.','Apoiar revisão de acessos, VPN e segmentação conforme o escopo.','Dar mais visibilidade para decisões sobre disponibilidade e proteção.','Organizar a conversa entre operação, risco e próximo passo.'];if(mod==='endpoint')return ['Acompanhar sinais do parque dentro do escopo contratado.','Apoiar prevenção, visibilidade, investigação e resposta.','Dar mais clareza sobre cobertura, consoles e pontos cegos.','Transformar alertas em contexto para a gestão agir melhor.'];return ['Acompanhar rotinas de cópia e eventos relacionados ao backup.','Apoiar leitura de falhas, retenção e capacidade de recuperação.','Dar mais clareza sobre o que está coberto e o que precisa de revisão.','Ajudar a preparar a empresa para responder com menos improviso.'];}
function conciergeValuePoints(mod:Module){if(mod==='firewall')return [{title:'Mais visibilidade',body:'Enxergar melhor links, acesso remoto, segmentação e borda.'},{title:'Mais controle',body:'Apoiar políticas, VPN e ajustes conforme a necessidade da operação.'},{title:'Mais previsibilidade',body:'Reduzir improviso quando algo sair do esperado.'}];if(mod==='endpoint')return [{title:'Mais cobertura',body:'Entender o que está protegido, o que está fora e o que pede resposta.'},{title:'Mais contexto',body:'Levar investigação e resposta para além do alerta isolado.'},{title:'Mais confiança',body:'Dar base para agir mais rápido quando algo acontecer.'}];return [{title:'Mais continuidade',body:'Enxergar o que precisa voltar primeiro e como isso pode acontecer.'},{title:'Mais confiança',body:'Discutir retenção, testes e capacidade de recuperação com mais clareza.'},{title:'Mais preparo',body:'Reduzir improviso quando a empresa precisar restaurar dados e serviços.'}];}
function conciergeRoleText(mod:Module){if(mod==='firewall')return 'Acompanhamento da borda e das rotinas de proteção previstas no serviço, com apoio à análise, visibilidade e condução do ambiente.';if(mod==='endpoint')return 'Acompanhamento do parque e dos sinais do endpoint, com apoio à análise, investigação e resposta dentro do serviço contratado.';return 'Acompanhamento das rotinas de backup e da leitura de falhas, com apoio à continuidade e à recuperação conforme o escopo contratado.';}
function clientRoleText(mod:Module){if(mod==='backup')return 'Definir criticidade, prioridades do negócio, janelas aceitáveis de parada e validações que dependam da equipe do cliente.';return 'Definir prioridades do negócio, aprovar mudanças, validar impactos operacionais e participar das decisões que dependam da realidade da empresa.';}
function storyCurrentState(mod:Module,attention:any[],pending:any[],profile:Profile,facts:Facts){const generic=(attention.length?attention:pending).slice(0,3).map(item=>item.title);if(generic.length)return generic;if(mod==='firewall')return ['Borda e acessos ainda precisam de mais confirmação.','Disponibilidade e segmentação seguem como pontos a validar.','Acesso remoto e inspeção merecem revisão.'];if(mod==='endpoint')return ['Cobertura e consoles ainda precisam de mais confirmação.','Parque e resposta a incidentes merecem revisão.','Existem pontos cegos a validar no ambiente.'];return ['Escopo de proteção ainda precisa de mais confirmação.','Retenção, testes e recuperação merecem revisão.','A empresa ainda precisa validar o que volta primeiro.'];}
function EnvironmentStoryStage({mod,profile,facts,stats}:{mod:Module;profile:Profile;facts:Facts;stats:[string,string][]}){const metrics=stats.slice(0,6);if(mod==='firewall'){const links=((profile as any).internetLinks||[]).filter((l:any)=>l?.provider||l?.speed);return <div className="story-environment"><div className="story-metric-grid">{metrics.map(([k,v])=><article key={k}><span>{k}</span><strong>{v}</strong></article>)}</div><div className="story-topology firewall"><div className="story-node wide"><small>Internet</small><strong>{links.length?plural(links.length,'link','links'):'Links a confirmar'}</strong><p>{links.map((l:any)=>`${l.provider||'Operadora'} ${l.speed||''}`.trim()).join(' · ')||'Velocidade e operadoras a confirmar'}</p></div><div className="story-topology-center"><div className="story-node core"><small>Perímetro atual</small><strong>{profile.firewallModel||'Firewall a confirmar'}</strong><p>{facts.ha==='yes'?'Alta disponibilidade informada':facts.haNeed==='yes'?'Alta disponibilidade a avaliar':'Alta disponibilidade não confirmada'}</p></div></div><div className="story-topology-branches"><article className="story-node"><small>Rede interna</small><strong>{profile.vlanCount||'0'} VLANs</strong><p>{profile.vlanNames||'Redes a mapear'}</p></article><article className="story-node"><small>Acesso remoto</small><strong>{facts.sslUsers||'0'} SSL VPN</strong><p>{facts.ipsecTunnels||'0'} túneis IPsec</p></article><article className="story-node"><small>Wi-Fi e borda</small><strong>{profile.apQuantity||'0'} APs</strong><p>{profile.switchCount||'0'} switches</p></article></div></div><div className="story-signal-row"><article><span>Disponibilidade</span><b>{facts.ha==='yes'?'Com redundância informada':facts.haNeed==='yes'?'Redundância em avaliação':'Ponto único a revisar'}</b></article><article><span>Inspeção</span><b>{label('inspection',facts.inspection||'unknown')}</b></article><article><span>Operação</span><b>{label('networkOps',facts.networkOps||'unknown')}</b></article></div></div>;}
if(mod==='endpoint'){const win=toCount((profile as any).endpointsWindows),mac=toCount((profile as any).endpointsMac),wsv=toCount((profile as any).windowsServerCount),lsv=toCount((profile as any).linuxServerCount),ood=toCount((profile as any).outOfDomainCount);const total=toCount(profile.deviceCount)||win+mac+wsv+lsv+ood;return <div className="story-environment"><div className="story-asset-overview"><article className="asset-total"><span>Parque informado</span><strong>{total||'a confirmar'}</strong><p>dispositivos e servidores considerados nesta conversa</p></article><article><span>Windows</span><strong>{win}</strong><p>{(profile as any).windowsVersion||'Versões a confirmar'}</p></article><article><span>macOS</span><strong>{mac}</strong><p>{(profile as any).macVersion||'Versões a confirmar'}</p></article><article><span>Servidores</span><strong>{wsv+lsv}</strong><p>{wsv} Windows e {lsv} Linux</p></article><article><span>Fora do domínio</span><strong>{ood}</strong><p>Dispositivos não gerenciados ou a confirmar</p></article></div><div className="story-signal-row"><article><span>Solução atual</span><b>{facts.endpointVendor||'A confirmar'}</b></article><article><span>Edição / licença</span><b>{facts.endpointLicense||'A confirmar'}</b></article><article><span>Cobertura</span><b>{facts.coverage||'A confirmar'}</b></article></div></div>;}
return <div className="story-environment"><div className="story-metric-grid">{metrics.map(([k,v])=><article key={k}><span>{k}</span><strong>{v}</strong></article>)}</div><div className="story-backup-grid"><article className="story-node wide"><small>O que precisa voltar primeiro</small><strong>{profile.backupMostCriticalSystem||'Serviço prioritário a confirmar'}</strong><p>Volume informado: {profile.backupTotalVolumeToProtect||'a confirmar'}</p></article><article className="story-node"><small>Retenção</small><strong>{profile.backupDesiredRetention||'A confirmar'}</strong><p>Frequência: {(profile as any).backupCurrentFrequency||'a confirmar'}</p></article><article className="story-node"><small>Parada tolerável</small><strong>{profile.backupMaxAcceptableDowntime||'A confirmar'}</strong><p>Perda de dados tolerável: {profile.backupMaxAcceptableDataLoss||'a confirmar'}</p></article><article className="story-node"><small>Escopo em nuvem</small><strong>{(profile as any).backupM365UsersCount||'0'} usuários M365</strong><p>Janela para cópia: {(profile as any).backupAvailableWindow||'a confirmar'}</p></article></div><div className="story-timeline"><span>Última cópia</span><i></i><span>Incidente</span><i></i><span>Retorno</span></div></div>;}
function pickDemoScenario(currentCompany?:string){const packs=[{profile:{companyName:'Atlas Distribuição',contactName:'Juliana Costa',sector:'Distribuição',userCount:85,deviceCount:112,itTeamSize:2,internetLinks:[{provider:'Fibra principal',speed:'700 Mbps',increaseSpeed:false,increaseSpeedNote:''},{provider:'Backup 5G',speed:'200 Mbps',increaseSpeed:false,increaseSpeedNote:''}],firewallModel:'Firewall atual a revisar',vlanCount:6,vlanNames:'Corporativo, convidados, financeiro, WMS, câmeras e servidores',switchCount:8,apQuantity:11,userGrowthEstimate:'Crescimento previsto de 20% no próximo ano'},facts:{meetingModules:'firewall',goal:'Disponibilidade e acesso remoto',context:'Primeira conversa com foco em rede, VPN e continuidade da operação.',firewall:'ngfw',ips:'yes',segmentation:'yes',vpn:'yes',mfa:'no',ha:'no',haNeed:'yes',inspection:'partial',networkOps:'reactive',sslUsers:'28',ipsecTunnels:'4',availability:'ERP e expedição dependem da conectividade.'}},{profile:{companyName:'Vida Plena Diagnósticos',contactName:'Marcelo Nunes',sector:'Saúde',userCount:55,deviceCount:73,itTeamSize:1,endpointsWindows:61,endpointsMac:4,windowsServerCount:4,linuxServerCount:2,outOfDomainCount:6,windowsVersion:'Windows 10 e 11',macVersion:'macOS recente'},facts:{meetingModules:'endpoint',goal:'Reduzir exposição em endpoints e responder melhor a incidentes',context:'Cliente quer entender cobertura atual e melhorar a capacidade de reação.',protection:'edr',console:'yes',endpointVendor:'Solução atual de antivírus tradicional',endpointLicense:'Plano básico',coverage:'67 protegidos, 6 fora',endpointOps:'reactive',response:'no',patch:'yes',admin:'shared',byod:'Uso pontual de dispositivos pessoais na operação.'}},{profile:{companyName:'Grupo Horizonte Engenharia',contactName:'Renato Almeida',sector:'Engenharia',userCount:120,deviceCount:140,itTeamSize:2,backupPhysicalServers:3,backupVirtualServers:14,backupDesktopsNotebooksCount:35,backupSolutionName:'Backup legado a revisar',backupTotalVolumeToProtect:'8 TB',backupDesiredRetention:'45 dias',backupCurrentFrequency:'Diária',backupMostCriticalSystem:'ERP, arquivos de projeto e banco SQL',backupMaxAcceptableDowntime:'8 horas',backupMaxAcceptableDataLoss:'4 horas',backupM365UsersCount:96,backupAvailableWindow:'Noite'},facts:{meetingModules:'backup',goal:'Continuidade e recuperação',context:'Cliente quer revisar escopo, retenção e capacidade real de restauração.',backup:'yes',tested:'no',isolated:'unknown',backupOps:'yes',recoveryPlan:'no',hosts:'3 hosts físicos, ambiente virtualizado',protectedVMs:'11',nas:'NAS local a confirmar',backupDest:'Repositório local e nuvem',cloudScope:'Microsoft 365 no escopo',appScope:'ERP, SQL e arquivos de projeto',lastTest:'Sem teste recente comprovado.'}},{profile:{companyName:'Nova Era Contábil',contactName:'Bianca Ramos',sector:'Serviços',userCount:34,deviceCount:41,itTeamSize:1,internetLinks:[{provider:'Fibra principal',speed:'500 Mbps',increaseSpeed:false,increaseSpeedNote:''}],firewallModel:'UTM legado',vlanCount:2,vlanNames:'Escritório e servidores',endpointsWindows:37,endpointsMac:2,backupMostCriticalSystem:'Sistema contábil e arquivos',backupTotalVolumeToProtect:'1,6 TB',backupDesiredRetention:'30 dias',backupMaxAcceptableDowntime:'6 horas',backupMaxAcceptableDataLoss:'2 horas'},facts:{meetingModules:'firewall',goal:'Organização do ambiente e visibilidade',context:'Cliente pequeno, com TI enxuta e necessidade de organizar a base antes de crescer.',firewall:'unknown',ips:'unknown',segmentation:'no',vpn:'yes',mfa:'no',ha:'no',haNeed:'unknown',inspection:'unknown',networkOps:'reactive',sslUsers:'9',ipsecTunnels:'0',availability:'Operação depende do sistema contábil e do acesso remoto.'}}];
 const pool=packs.filter(item=>item.profile.companyName!==currentCompany);return pool[Math.floor(Math.random()*pool.length)]||packs[0];}

function ImpactLab({facts,update}:{facts:Facts;update:(key:string,v:string)=>void}){
 const cost=facts.internalCost||'',hours=facts.internalHours||'',recovery=facts.internalRecovery||'',monthly=facts.internalMonthly||'',setup=facts.internalSetup||''; const setCost=(v:string)=>update('internalCost',v),setHours=(v:string)=>update('internalHours',v),setRecovery=(v:string)=>update('internalRecovery',v),setMonthly=(v:string)=>update('internalMonthly',v),setSetup=(v:string)=>update('internalSetup',v);const [show,setShow]=useState(false);
 const number=(s:string)=>Math.max(0,Number(s)||0);const impact=number(cost)*number(hours)+number(recovery);const ready=cost!==''&&hours!=='';const investment=number(setup)+12*number(monthly);
 return <section className="v3-stage"><span className="v3-kicker">PREMISSAS PARA DISCUSSÃO</span><h2>Quanto uma parada representaria?</h2><p className="v3-lead">Use informações do cliente para explorar um cenário de indisponibilidade. Valores não informados permanecem em aberto.</p><div className="v3-form-grid">{[['Custo estimado por hora parada (R$)',cost,setCost],['Horas de parada no cenário',hours,setHours],['Custo adicional de recuperação (R$)',recovery,setRecovery]].map(([s,v,fn])=><label className="v3-field" key={String(s)}><span>{String(s)}</span><input type="number" min="0" value={String(v)} onChange={e=>(fn as (s:string)=>void)(e.target.value)}/></label>)}</div><div className="v3-impact-result"><span>Impacto do cenário informado</span><strong>{ready?money(impact):'Informe as premissas'}</strong><p>Custo por hora × horas de parada + recuperação adicional. Sem probabilidade automática ou projeção de economia.</p></div><button className="v3-btn secondary" onClick={()=>setShow(!show)}>{show?'Ocultar':'Abrir'} simulação de investimento</button>{show&&<div className="v3-panel v3-subsection"><p>Preencha somente se for pertinente à reunião e permitido pela política comercial.</p><div className="v3-form-grid"><label className="v3-field"><span>Implantação (R$)</span><input min="0" type="number" value={setup} onChange={e=>setSetup(e.target.value)}/></label><label className="v3-field"><span>Mensalidade (R$)</span><input min="0" type="number" value={monthly} onChange={e=>setMonthly(e.target.value)}/></label></div><h3>Investimento em 12 meses: {monthly!==''?money(investment):'a informar'}</h3><p>Implantação + 12 mensalidades. Simulação, sujeita à proposta formal. Esses valores não são incluídos na devolutiva exportada.</p></div>}</section>;
}
function RecoveryLab(){const [interval,setIntervalHours]=useState(24);const [target,setTarget]=useState(4);return <div className="v3-panel v3-subsection"><h3>Janela de cópia e objetivo de retorno</h3><p>Exercício hipotético. Ajuste para discutir a necessidade do cliente.</p><label className="v3-field"><span>Intervalo hipotético entre cópias: {interval}h</span><input type="range" min="1" max="48" value={interval} onChange={e=>setIntervalHours(Number(e.target.value))}/></label><label className="v3-field"><span>Objetivo de tempo de recuperação: {target}h</span><input type="range" min="1" max="48" value={target} onChange={e=>setTarget(Number(e.target.value))}/></label><div className="v3-recovery-bar"><span style={{width:`${interval/48*100}%`}}>Cópias: {interval}h</span></div><div className="v3-recovery-bar target"><span style={{width:`${target/48*100}%`}}>Objetivo: {target}h</span></div><p className="v3-footnote">O intervalo entre cópias ajuda a discutir a perda possível, mas não comprova o RPO atendido. O tempo de retorno precisa ser validado em teste.</p></div>;}
